func randRoute(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	p := ""
	for i := 0; i < n; i++ {
		p += "/" + segs[rnd.Intn(len(segs))]
	}
	if rnd.Intn(6) == 0 {
		p += "/"
	}
	if rnd.Intn(6) == 0 {
		p += "*"
	}
	return p
}

func randPath(rnd *rand.Rand) string {
	n := rnd.Intn(6)
	p := ""
	for i := 0; i < n; i++ {
		p += "/" + segs[rnd.Intn(len(segs))]
	}
	if rnd.Intn(4) == 0 {
		p += "/"
	}
	if rnd.Intn(10) == 0 {
		p = p[1:]
	}
	return p
}

func main() {
	seed := int64(1)
	if len(os.Args) > 1 {
		v, _ := strconv.Atoi(os.Args[1])
