package echo

import (
	"net/http"
	"testing"

	"github.com/stretchr/testify/assert"
)

// TEMPORARY reproduction test - deleted after verification.
func TestTmpContext_Scheme(t *testing.T) {
	tests := []struct {
		name string
		c    Context
		s    string
	}{
		{
			name: "TLS",
			c: &context{
				request: &http.Request{TLS: &tls.ConnectionState{}},
			},
			s: "https",
		},
		{
			name: "X-Forwarded-Proto https",
			c: &context{
				request: &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"https"}}},
			},
			s: "https",
		},
		{
			name: "X-Forwarded-Protocol http",
			c: &context{
				request: &http.Request{Header: http.Header{HeaderXForwardedProtocol: []string{"http"}}},
			},
			s: "http",
		},
		{
			name: "X-Forwarded-Ssl on",
			c: &context{
				request: &http.Request{Header: http.Header{HeaderXForwardedSsl: []string{"on"}}},
			},
			s: "https",
		},
		{
			name: "X-Url-Scheme https",
			c: &context{
				request: &http.Request{Header: http.Header{HeaderXUrlScheme: []string{"https"}}},
			},
			s: "https",
		},
		{
			name: "nothing",
			c:    &context{request: &http.Request{}},
			s:    "http",
		},
		{
			name: "ignores invalid X-Forwarded-Proto and uses X-Forwarded Protocol",
			c: &context{
				request: &http.Request{Header: http.Header{
					HeaderXForwardedProto:    []string{"invalid"},
					HeaderXForwardedProtocol: []string{"https"},
				}},
			},
			s: "https",
		},
		{
			name: "ignores invalid forwarded headers and falls back to http",
			c: &context{
				request: &http.Request{Header: http.Header{
					HeaderXForwardedProto:    []string{"invalid"},
					HeaderXForwardedProtocol: []string{"invalid"},
					HeaderXForwardedSsl:      []string{"off"},
					HeaderXUrlScheme:         []string{"invalid"},
				}},
			},
			s: "http",
		},
		{
			name: "invalid proto, ssl on",
			c: &context{
				request: &http.Request{Header: http.Header{
					HeaderXForwardedProto: []string{"garbage"},
					HeaderXForwardedSsl:   []string{"on"},
				}},
			},
			s: "https",
		},
		{
			name: "invalid proto, X-Url-Scheme https",
			c: &context{
				request: &http.Request{Header: http.Header{
					HeaderXForwardedProto: []string{"garbage"},
					HeaderXUrlScheme:      []string{"https"},
				}},
			},
			s: "https",
		},
		{
			name: "mixed case valid proto is returned",
			c: &context{
				request: &http.Request{Header: http.Header{
					HeaderXForwardedProto: []string{"HTTPS"},
				}},
			},
			s: "HTTPS",
		},
		{
			name: "TLS wins over invalid headers",
			c: &context{
				request: &http.Request{
					TLS:    &tls.ConnectionState{},
					Header: http.Header{HeaderXForwardedProto: []string{"garbage"}},
				},
			},
			s: "https",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.s, tt.c.Scheme())
		})
	}
}

