package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"

	"github.com/labstack/echo/v4"
)

func scheme(h map[string]string) string {
	e := echo.New()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	for k, v := range h {
		req.Header.Set(k, v)
	}
	return e.NewContext(req, nil).Scheme()
}

func main() {
	cases := []struct {
		name string
		h    map[string]string
		want string
	}{
		{"invalid Proto + Protocol=https", map[string]string{"X-Forwarded-Proto": "invalid", "X-Forwarded-Protocol": "https"}, "https"},
		{"all forwarded headers invalid", map[string]string{"X-Forwarded-Proto": "invalid", "X-Forwarded-Protocol": "invalid", "X-Forwarded-Ssl": "off", "X-Url-Scheme": "invalid"}, "http"},
		{"valid Proto=https", map[string]string{"X-Forwarded-Proto": "https"}, "https"},
		{"valid Protocol=http", map[string]string{"X-Forwarded-Protocol": "http"}, "http"},
		{"Ssl=on", map[string]string{"X-Forwarded-Ssl": "on"}, "https"},
		{"UrlScheme=https", map[string]string{"X-Url-Scheme": "https"}, "https"},
		{"no headers", map[string]string{}, "http"},
		{"invalid Proto + Ssl=on", map[string]string{"X-Forwarded-Proto": "garbage", "X-Forwarded-Ssl": "on"}, "https"},
		{"invalid Proto + UrlScheme=https", map[string]string{"X-Forwarded-Proto": "garbage", "X-Url-Scheme": "https"}, "https"},
		{"invalid Proto + invalid Protocol + Ssl=on", map[string]string{"X-Forwarded-Proto": "ftp", "X-Forwarded-Protocol": "ftp", "X-Forwarded-Ssl": "on"}, "https"},
	}
	fail := 0
	for _, c := range cases {
		got := scheme(c.h)
		status := "OK  "
		if got != c.want {
			status = "FAIL"
			fail++
		}
		fmt.Printf("%s %-45s got=%-8q want=%q\n", status, c.name, got, c.want)
	}
	if fail > 0 {
		fmt.Printf("%d FAILURES\n", fail)
		os.Exit(1)
	}
	fmt.Println("all scheme assertions passed")
}
