package repro

import (
	"fmt"
	"math/rand"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
)

type op struct {
	kind string // "group", "route"
	g    int
	path string
	mw   string
}

func build(t *testing.T, ops []op, tr *[]string) *echo.Echo {
	e := echo.New()
	groups := map[int]*echo.Group{}
	for _, o := range ops {
		switch o.kind {
		case "group":
			if o.mw != "" {
				groups[o.g] = e.Group(o.path, mkMW2(tr, o.mw))
			} else {
				groups[o.g] = e.Group(o.path)
			}
		case "route":
			g := groups[o.g]
			if g == nil {
				t.Fatalf("route before group: %+v", o)
			}
			g.GET(o.path, mkH2(tr, fmt.Sprintf("h%d%s", o.g, o.path)))
		}
	}
	return e
}

func mkMW2(tr *[]string, name string) echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c echo.Context) error {
			*tr = append(*tr, name)
			return next(c)
		}
	}
}
func mkH2(tr *[]string, name string) echo.HandlerFunc {
	return func(c echo.Context) error {
		*tr = append(*tr, name)
		return c.String(200, name)
	}
}

func TestFuzzOrder(t *testing.T) {
	rng := rand.New(rand.NewSource(42))
	paths := []string{"/a", "/b", "/c", "/a/b", "/a/c", "/b/c"}
	prefixes := []string{"/x", "/x", "/y"}
	for iter := 0; iter < 300; iter++ {
		// build a canonical op list
		nGroups := 2 + rng.Intn(2)
		var base []op
		for i := 0; i < nGroups; i++ {
			base = append(base, op{kind: "group", g: i, path: prefixes[rng.Intn(len(prefixes))], mw: fmt.Sprintf("mw%d", i)})
		}
		nRoutes := 2 + rng.Intn(4)
		for i := 0; i < nRoutes; i++ {
			base = append(base, op{kind: "route", g: rng.Intn(nGroups), path: paths[rng.Intn(len(paths))]})
		}
		// dedupe routes by (group,path) to avoid ambiguity of same route twice
		seen := map[string]bool{}
		var ops []op
		for _, o := range base {
			if o.kind == "route" {
				k := fmt.Sprintf("%d|%s", o.g, o.path)
				if seen[k] {
					continue
				}
				seen[k] = true
			}
			ops = append(ops, o)
		}
		// shuffle while keeping group creation before its routes
		shuffled := make([]op, len(ops))
		copy(shuffled, ops)
		for i := len(shuffled) - 1; i > 0; i-- {
			j := rng.Intn(i + 1)
			shuffled[i], shuffled[j] = shuffled[j], shuffled[i]
		}
		// fix: ensure group creation precedes its routes
		ok := true
		created := map[int]bool{}
		for _, o := range shuffled {
			if o.kind == "group" {
				created[o.g] = true
			} else if !created[o.g] {
				ok = false
			}
		}
		if !ok {
			continue
		}

		var tr1, tr2 []string
		e1 := build(t, ops, &tr1)
		e2 := build(t, shuffled, &tr2)

		// expected chain per (group,path)
		for _, o := range ops {
			if o.kind != "route" {
				continue
			}
			full := prefixes[0]
			_ = full
			// find group prefix
			var gprefix, gmw string
			for _, g := range ops {
				if g.kind == "group" && g.g == o.g {
					gprefix = g.path
					gmw = g.mw
				}
			}
			url := gprefix + o.path
			want := fmt.Sprintf("[%s h%d%s]", gmw, o.g, o.path)

			for _, tc := range []struct {
				name string
				e    *echo.Echo
				tr   *[]string
			}{{"canonical", e1, &tr1}, {"shuffled", e2, &tr2}} {
				*tc.tr = nil
				rec := httptest.NewRecorder()
				req := httptest.NewRequest(http.MethodGet, url, nil)
				tc.e.ServeHTTP(rec, req)
				got := fmt.Sprint(*tc.tr)
				if got != want {
					t.Errorf("iter %d %s: GET %s chain=%s want=%s\nops=%+v\nshuffled=%+v", iter, tc.name, url, got, want, ops, shuffled)
					return
				}
			}
		}
	}
}
